```r
library(pROC)


# =========================================================================
# 1. Load PRS and phenotype data
# =========================================================================

# Load the PRS profile generated by the PRS analysis
data1 <- read.table(
    'all/hiv_eur/PRScs/eur/eur.profile',
    header = T
)

# Load the phenotype and study information
data2 <- read.table(
    '../data/pheno/allsite.tsv',
    header = T
)

# Merge PRS and phenotype data using the first two columns
# as individual identifiers
all <- merge(
    data1,
    data2,
    by = c(1, 2)
)

# Calculate the PRS for each individual
# SCORE = PRS score per allele and CNT = number of alleles/SNPs
all$sumscore <- all$SCORE * all$CNT


# =========================================================================
# 2. Define the number of PCs used for each study site
# =========================================================================

# Different numbers of principal components are used for each study site.
# The site name is used as the key to retrieve the corresponding number
# of PCs below (pcsn[[site]]).
pcsn <- list(
    "jcs_breast" = 6,
    "jcs_oscc" = 6,
    "jcs_control" = 6,
    "jcs_cervical" = 6,
    "South" = 5,
    "ark" = 2,
    "East" = 5,
    "West" = 5
)


# =========================================================================
# 3. Analysis of all participants
# =========================================================================

cmt <- 1
listn <- c()

# Analyse each study site separately.
#
# 'site' is the name of the current study site.
# 'site_all' contains only participants belonging to that site.
for (site in unique(all$Study.Site)) {

    # Select participants from the current study site
    site_all <- all[all$Study.Site == site, ]


    # ---------------------------------------------------------------------
    # Load principal components for the current study site
    # ---------------------------------------------------------------------

    # Each study site has its own PC file.
    # For example:
    # pcs_res/jcs_breast_all.eigenvec
    pcs <- read.table(
        paste(
            'pcs_res/',
            site,
            '_all.eigenvec',
            sep = ''
        ),
        comment.char = '',
        header = T
    )

    # Merge the PCs with the PRS and phenotype data
    site_all <- merge(
        site_all,
        pcs,
        by = c(1, 2)
    )


    # ---------------------------------------------------------------------
    # Residualize the PRS
    # ---------------------------------------------------------------------

    # Build the adjustment model dynamically.
    #
    # The model includes:
    #   - sex
    #   - age
    #   - the number of PCs defined for the current study site
    #
    # For example, if pcsn[[site]] = 6:
    # sumscore ~ sex + age + PC1 + PC2 + PC3 + PC4 + PC5 + PC6
    formula1 <- paste(
        'sumscore~',
        paste(
            c(
                'sex',
                'age',
                paste(
                    'PC',
                    1:pcsn[[site]],
                    sep = ''
                )
            ),
            collapse = '+'
        ),
        sep = ''
    )

    # Calculate residuals from the PRS adjustment model.
    # These residuals represent the part of the PRS not explained
    # by sex, age and the selected principal components.
    site_all$sumscore_residuals <- glm(
        as.formula(formula1),
        data = site_all
    )$residuals


    # ---------------------------------------------------------------------
    # ROC / AUC analysis
    # ---------------------------------------------------------------------

    # Evaluate how well the adjusted PRS discriminates HIV status.
    rocauc <- roc(
        site_all$hiv,
        site_all$sumscore_residuals,
        direction = '<'
    )

    # Calculate the confidence interval for the AUC
    ciauc <- ci(rocauc)

    aucres <- data.frame(
        auc = rocauc$auc,
        auc_ci5 = ciauc[1],
        auc_ci95 = ciauc[2]
    )


    # ---------------------------------------------------------------------
    # Logistic regression
    # ---------------------------------------------------------------------

    # Build the logistic regression model:
    #
    # HIV status ~ PRS + sex + age + principal components
    formula2 <- paste(
        'hiv~sumscore+',
        paste(
            c(
                'sex',
                'age',
                paste(
                    'PC',
                    1:pcsn[[site]],
                    sep = ''
                )
            ),
            collapse = '+'
        ),
        sep = ''
    )

    # Fit the logistic regression model
    gm1 <- glm(
        as.formula(formula2),
        data = site_all,
        family = "binomial"
    )

    # Extract the model summary and the PRS coefficient
    sm <- summary(gm1)
    sm2 <- sm$coefficients[2, ]


    # ---------------------------------------------------------------------
    # Store results from the current study site
    # ---------------------------------------------------------------------

    if (cmt == 1) {
        aucresf <- aucres
    } else {
        aucresf <- rbind(
            aucresf,
            aucres
        )
    }

    # Store the number of participants analysed at this site
    listn <- c(
        listn,
        nrow(site_all)
    )

    # Store the logistic regression results
    if (cmt == 1) {
        smf <- sm2
    } else {
        smf <- rbind(
            smf,
            sm2
        )
    }

    cmt <- cmt + 1
}


# Combine study-site results into one table
smf <- cbind(
    study.site = unique(all$Study.Site),
    as.data.frame(smf),
    aucresf,
    n = listn
)

# Save results for all participants
write.csv(
    smf,
    file = 'all_prsrs.csv',
    row.names = F
)


