    if (cmt == 1) {
        smf <- sm2
    } else {
        smf <- rbind(
            smf,
            sm2
        )
    }

    cmt <- cmt + 1
}


# Combine and save results
smf <- cbind(
    study.site = unique(all_men$Study.Site),
    as.data.frame(smf),
    aucresf,
    n = listn
)

write.csv(
    smf,
    file = 'all_men_prsrs.csv',
    row.names = F
